(ns fastmath.signal.chirp-test
  (:require [fastmath.signal.chirp :as sut]
            [fastmath.signal :as sig]
            [clojure.test :as t]
            [clojure.java.io :as io]
            [clojure.edn :as edn]))

;; scipy.signal.chirp values (phi = -90 + 360 phase0), generated by
;; `utils/fastmath/dev/generate_chirp_reference.py` into `test/resources/signal/chirp_reference.edn`:
;; 5 methods x sweeps 1->6, 6->1, 3->3 (t1 = 2) x phase0 0, 0.25 on 301 points of [0, 3] shifted by
;; 0.0013 (the hyperbolic singularity of the 1->6 sweep, t = 2.4, is passed but not sampled).

(def ^:private reference
  (delay (edn/read-string (slurp (io/resource "signal/chirp_reference.edn")))))

(defn- max-diff
  [a b]
  (reduce max 0.0 (map #(Math/abs (- (double %1) (double %2))) a b)))

(t/deftest chirps-vs-scipy
  (let [ts (:t @reference)]
    (doseq [{:keys [type y] :as opts} (:chirps @reference)
            :let [opts (dissoc opts :y :type)
                  w (sig/chirp type opts)]]
      ;; phases up to ~20 cycles computed in another order; measured maximum difference 3.3e-14
      (t/is (<= (max-diff y (map w ts)) 1.0e-12) (str type " " opts)))))

(t/deftest phase-functions
  (t/is (= 0.25 ((sut/->constant {:f0 2.0 :phase0 0.25}) 0.0)))
  (t/is (= 4.25 ((sut/->constant {:f0 2.0 :phase0 0.25}) 2.0)))
  (t/is (= ((sut/->constant {:f0 3.0}) 1.7) ((sut/->logarithmic {:f0 3.0 :f1 3.0}) 1.7)) "f0 = f1: constant")
  (t/is (= ((sut/->constant {:f0 3.0}) 1.7) ((sut/->hyperbolic {:f0 3.0 :f1 3.0}) 1.7)) "f0 = f1: constant")
  (t/is (Double/isFinite ((sut/->hyperbolic {:f0 1.0 :f1 6.0 :time 2.0}) 3.0)) "beyond the singularity")
  (t/is (= 0.0 ((sut/->linear) 0.0)))
  (t/is (== 2.5 ((sut/->linear) 1.0)) "default 0 -> 5 Hz in 1 s"))

(t/deftest guards
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/->linear {:time 0.0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/->quadratic-up {:time -1.0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/->quadratic-down {:time 0.0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/->logarithmic {:f0 0.0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/->logarithmic {:f1 -1.0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/->hyperbolic {:f0 0.0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sig/chirp :exponential)))
  (t/is (= ((sig/waveform :sine {:f 2.0}) 0.3) ((sig/chirp :constant {:f0 2.0}) 0.3)) ":constant via signal/chirp"))
